<template>
<section class="delivery-route-timeline">
    <header>
        <h2>{{routeName}}</h2>
        <span>完成 {{completedCount}}/{{stops.length}}</span>
    </header>
    <div class="route-layout">
        <ol>
            <li s-for="stop in stops trackby stop.id" class="{{stop.status}}" on-click="select(stop.id)">
                <i></i>
                <div>
                    <strong>{{stop.name}}</strong>
                    <span>预计 +{{stop.eta}} 分钟</span>
                </div>
            </li>
        </ol>
        <aside s-if="selectedStop">
            <h3>{{selectedStop.name}}</h3>
            <label>
                增加延误
                <input type="number" value="{{delay}}" on-input="updateDelay">
            </label>
            <button on-click="applyDelay">应用延误</button>
            <button class="primary" on-click="advance">到达并前往下一站</button>
        </aside>
    </div>
</section>
</template>

<script>
const san = require('san');
const DataTypes = san.DataTypes;

module.exports = san.defineComponent({
    name: 'DeliveryRouteTimeline',
    components: {},
    initData() {
        return {
            routeName: '城西配送线',
            initialStops: [
                {
                    "id": 1,
                    "name": "分拨中心",
                    "eta": 0,
                    "status": "done"
                },
                {
                    "id": 2,
                    "name": "大学城",
                    "eta": 25,
                    "status": "active"
                },
                {
                    "id": 3,
                    "name": "科技园",
                    "eta": 55,
                    "status": "waiting"
                }
            ],
            stops: [],
            selectedId: 2,
            delay: 0
        };
    },
    dataTypes: {
        routeName: DataTypes.string,
        initialStops: DataTypes.array,
        stops: DataTypes.array,
        selectedId: DataTypes.number,
        delay: DataTypes.number
    },
    computed: {
        completedCount() {
            const stops = this.data.get('stops') || [];
            return stops.filter(item => item.status === 'done').length;
        },
        selectedStop() {
            const stops = this.data.get('stops') || [];
            const selectedId = this.data.get('selectedId');
            return stops.find(item => item.id === selectedId) || null;
        }
    },
    inited() {
        const initialStops = this.data.get('initialStops') || [];
        const stops = initialStops.map(item => Object.assign({}, item));
        this.data.set('stops', stops);
    },
    select(id) {
        this.data.set('selectedId', id);
    },
    advance() {
        const stops = this.data.get('stops') || [];
        const index = stops.findIndex(item => item.status === 'active');
        if (index < 0) return;
        const next = stops.map((item, i) => {
            const status = i === index ? 'done' : i === index + 1 ? 'active' : item.status;
            return Object.assign({}, item, { status });
        });
        this.data.set('stops', next);
        this.fire('status', next);
    },
    updateDelay(event) {
        const value = Number(event.target.value) || 0;
        this.data.set('delay', value);
    },
    applyDelay() {
        const selected = this.data.get('selectedStop');
        const delay = this.data.get('delay');
        if (!selected || !delay) return;
        const stops = this.data.get('stops') || [];
        const newStops = stops.map(item => {
            if (item.eta >= selected.eta) {
                return Object.assign({}, item, { eta: item.eta + delay });
            }
            return item;
        });
        this.data.set('stops', newStops);
        this.data.set('delay', 0);
    }
});
</script>

